def solve(data):
    packages = data['packages']
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    names = sorted(packages)

    if any(name not in packages for name in roots):
        return {'error': 'unsatisfiable'}

    constraints = {
        name: [(interval[0], interval[1])]
        for name, interval in roots.items()
    }
    best = None
    best_vector = None

    def search(assigned, required, limits):
        nonlocal best, best_vector
        unresolved = sorted(required - set(assigned))
        if not unresolved:
            vector = tuple(assigned[name] if name in assigned else -1 for name in names)
            if best_vector is None or vector > best_vector:
                best = dict(assigned)
                best_vector = vector
            return

        name = unresolved[0]
        for row in choose(packages[name]):
            version = row['version']
            if any(not (low <= version <= high) for low, high in limits.get(name, [])):
                continue
            if version in blocked.get(name, []):
                continue
            if name in pins and version != pins[name]:
                continue

            deps = row.get('deps', [])
            if any(dep['name'] not in packages for dep in deps):
                continue

            next_assigned = dict(assigned)
            next_assigned[name] = version
            next_required = required | {dep['name'] for dep in deps}
            next_limits = {key: list(ranges) for key, ranges in limits.items()}
            feasible = True
            for dep in deps:
                dep_name = dep['name']
                low, high = dep['min'], dep['max']
                next_limits.setdefault(dep_name, []).append((low, high))
                if dep_name in next_assigned and not (low <= next_assigned[dep_name] <= high):
                    feasible = False
                    break
            if feasible:
                search(next_assigned, next_required, next_limits)

    search({}, set(roots), constraints)
    if best is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best}
